"""Đồng bộ các file .py / .txt trong thư mục code/ sang code_registry.js (dùng khi mở HTML trực tiếp bằng file://)."""
import json
from pathlib import Path

CODE_DIR = Path(__file__).resolve().parent
HTML_ROOT = CODE_DIR.parent

def build_registry() -> int:
    files = {}
    for path in sorted(CODE_DIR.rglob("*")):
        if path.is_file() and path.suffix in {".py", ".txt"} and path.name != "sync_registry.py":
            rel = "./" + path.relative_to(HTML_ROOT).as_posix()
            files[rel] = path.read_text(encoding="utf-8")
    out_js = (
        "// Auto-generated by code/sync_registry.py for offline file:// fallback.\n"
        "// When served over HTTP/Live Server, js/code-loader.js fetches the .py files directly.\n"
        "window.SYLLABUS_CODE_FILES = "
        + json.dumps(files, ensure_ascii=False, indent=2)
        + ";\n"
    )
    (CODE_DIR / "code_registry.js").write_text(out_js, encoding="utf-8", newline="\n")
    return len(files)

if __name__ == "__main__":
    n = build_registry()
    print(f"Synced {n} external code files into code/code_registry.js")
